import{_ as i}from"./chunks/Audio.COine8Wh.js";import{_ as t}from"./chunks/Tags.BJ536pW3.js";import{c as o,o as s,j as a,G as l,ae as n,a as r}from"./chunks/framework.Bw0Gm4PQ.js";const u=JSON.parse('{"title":"Miracle on Ice Congressional Gold Medal Act","description":"","frontmatter":{"legisId":"2025-12-12-miracle-on-ice-congressional-gold-medal-act","title":"Miracle on Ice Congressional Gold Medal Act","displayTitle":"Miracle on Ice Congressional Gold Medal Act","lawNumber":"119-53","billNumber":"H.R. 452","sourceUrl":"https://www.govinfo.gov/bulkdata/PLAW/119/public/PLAW-119publ53.xml","publishDate":"2025-12-12T00:00:00-05:00","industries":["government-operations"],"agencies":["Department of the Treasury","United States Mint"],"head":[["script",{"type":"application/ld+json"},"[{\\"@context\\":\\"https://schema.org\\",\\"@type\\":\\"BreadcrumbList\\",\\"itemListElement\\":[{\\"@type\\":\\"ListItem\\",\\"position\\":1,\\"name\\":\\"Home\\",\\"item\\":\\"https://vladroff.github.io/legis\\"},{\\"position\\":2,\\"@type\\":\\"ListItem\\",\\"name\\":\\"Congress Bills\\",\\"item\\":\\"https://vladroff.github.io/legis/congress-bills\\"},{\\"position\\":3,\\"@type\\":\\"ListItem\\",\\"name\\":\\"Miracle on Ice Congressional Gold Medal Act\\",\\"item\\":\\"https://vladroff.github.io/legis/congress-bills/2025-12-12-miracle-on-ice-congressional-gold-medal-act\\"}]},{\\"@context\\":\\"https://schema.org\\",\\"@type\\":\\"Article\\",\\"headline\\":\\"Miracle on Ice Congressional Gold Medal Act\\",\\"description\\":\\"Summaries of US legislation.\\",\\"url\\":\\"https://vladroff.github.io/legis/congress-bills/2025-12-12-miracle-on-ice-congressional-gold-medal-act\\",\\"datePublished\\":\\"2025-12-12T00:00:00-05:00\\",\\"dateModified\\":1788887623000,\\"mainEntityOfPage\\":\\"https://vladroff.github.io/legis/congress-bills/2025-12-12-miracle-on-ice-congressional-gold-medal-act\\",\\"author\\":{\\"@type\\":\\"Organization\\",\\"name\\":\\"Legis\\"},\\"publisher\\":{\\"@type\\":\\"Organization\\",\\"name\\":\\"Legis\\"}}]"]]},"headers":[],"relativePath":"congress-bills/2025-12-12-miracle-on-ice-congressional-gold-medal-act.md","filePath":"congress-bills/2025-12-12-miracle-on-ice-congressional-gold-medal-act.md","lastUpdated":1788887623000}'),c={name:"congress-bills/2025-12-12-miracle-on-ice-congressional-gold-medal-act.md"},b=Object.assign(c,{setup(d){return(m,e)=>(s(),o("div",null,[e[0]||(e[0]=a("h1",{id:"miracle-on-ice-congressional-gold-medal-act",tabindex:"-1"},[r("Miracle on Ice Congressional Gold Medal Act "),a("a",{class:"header-anchor",href:"#miracle-on-ice-congressional-gold-medal-act","aria-label":'Permalink to "Miracle on Ice Congressional Gold Medal Act"'},"​")],-1)),l(i),l(t,{list:"/congress-bills"}),e[1]||(e[1]=n('<p>Signed into law on Friday, December 12, 2025. Public Law 119-53, H.R. 452.</p><p><strong>Headline:</strong> Congress honors the 1980 U.S. Olympic Men’s Ice Hockey Team with three Congressional Gold Medals.</p><p><strong>Why it matters:</strong> The medals recognize the team’s historic Olympic victory, including the “Miracle on Ice,” and its impact on American morale and hockey.</p><p><strong>What the law does:</strong></p><ul><li>Directs the Treasury to design and produce three Congressional Gold Medals.</li><li>Places one medal each at the Lake Placid Olympic Center, United States Hockey Hall of Fame Museum, and United States Olympic &amp; Paralympic Museum for display and research.</li><li>Allows the Treasury to make and sell bronze duplicates, with costs and proceeds handled through the United States Mint Public Enterprise Fund.</li></ul><p><strong>Who it affects:</strong></p><ul><li>Members of the 1980 U.S. Olympic Men’s Ice Hockey Team.</li><li>The three museums receiving the medals.</li><li>The Department of the Treasury and United States Mint.</li></ul><p><strong>Practical impact on a regular person:</strong></p><ul><li>Visitors can view the medals and learn about the team’s achievement at the designated museums.</li><li>Members of the public may buy bronze duplicates from the Treasury.</li></ul><h2 id="breakdown" tabindex="-1">Breakdown <a class="header-anchor" href="#breakdown" aria-label="Permalink to &quot;Breakdown&quot;">​</a></h2><h3 id="miracle-on-ice-congressional-gold-medal-act-1" tabindex="-1">Miracle on Ice Congressional Gold Medal Act <a class="header-anchor" href="#miracle-on-ice-congressional-gold-medal-act-1" aria-label="Permalink to &quot;Miracle on Ice Congressional Gold Medal Act&quot;">​</a></h3><p>This law awards three Congressional Gold Medals to the members of the 1980 U.S. Olympic Men’s Ice Hockey Team for their historic “Miracle on Ice” achievement and its impact on American morale and hockey. The medals will be placed in three museums, and the Treasury may sell bronze duplicates to cover production costs.</p><p><strong>Key takeaways:</strong></p><ul><li>Congress will collectively honor the members of the 1980 U.S. Olympic Men’s Ice Hockey Team with three Congressional Gold Medals.</li><li>The medals recognize the team’s Olympic gold medal run, including its historic victory over the Soviet Union.</li><li>One medal each will go to the Lake Placid Olympic Center, the United States Hockey Hall of Fame Museum, and the United States Olympic &amp; Paralympic Museum for display and research.</li><li>The Treasury will design and produce the gold medals and may make and sell bronze duplicates.</li><li>The United States Mint Public Enterprise Fund will pay production costs and receive proceeds from bronze medal sales.</li></ul><p>Source: <a href="https://www.govinfo.gov/bulkdata/PLAW/119/public/PLAW-119publ53.xml" target="_blank" rel="noreferrer">https://www.govinfo.gov/bulkdata/PLAW/119/public/PLAW-119publ53.xml</a></p>',15))]))}});export{u as __pageData,b as default};
